for (const [locale, values] of Object.entries(accountMessageRows)) {
  if (values.length !== accountMessageKeys.length) throw new Error(`Incomplete ${locale} account messages`);
  for (const [index, value] of values.entries()) {
    const tokens = (value.match(/\{\w+\}/g) || []).sort().join(",");
    const reference = (accountMessageRows.en[index].match(/\{\w+\}/g) || []).sort().join(",");
    if (tokens !== reference) throw new Error(`Invalid ${locale} placeholders for ${accountMessageKeys[index]}`);
  }
  Object.assign(common[locale], Object.fromEntries(accountMessageKeys.map((key, index) => [key, values[index]])));
}
