for (const [locale, values] of Object.entries(feedbackRows)) {
  if (values.length !== feedbackKeys.length) throw new Error(`Incomplete ${locale} preview feedback`);
  for (const [index, value] of values.entries()) {
    const tokens = (value.match(/\{\w+\}/g) || []).sort().join(",");
    const reference = (feedbackRows.en[index].match(/\{\w+\}/g) || []).sort().join(",");
    if (tokens !== reference) throw new Error(`Invalid ${locale} placeholders for ${feedbackKeys[index]}`);
  }
  Object.assign(common[locale], Object.fromEntries(feedbackKeys.map((key, index) => [key, values[index]])));
}
