export function publicDeveloperGuideUrl(name, locale = currentLanguage) {
  const filename = locale === "zh" ? name : name.replace(/\.md$/, ".en.md");
  return "https://github.com/kasamila/kasamila-dev/blob/main/docs/" + filename;
}
export function localizedPortalUrl(href, base, locale = currentLanguage) {
  const url = new URL(href, base);
  if (url.origin !== new URL(base).origin || !/^\/portal(?:\/|$)/.test(url.pathname)) return href;
  if (!Object.hasOwn(catalogs, locale)) return href;
  url.searchParams.set("lang", locale);
  return url.pathname + url.search + url.hash;
}
export function applyTranslations() {
  document.documentElement.lang = currentLanguage === "zh" ? "zh-CN" : currentLanguage;
  document.documentElement.dir = currentLanguage === "ar" ? "rtl" : "ltr";
  document.querySelectorAll("[data-i18n]").forEach((node) => {
    const value = t(node.dataset.i18n);
    if (node.dataset.i18n === "hero.title") node.innerHTML = value;
    else if (value !== node.dataset.i18n) node.textContent = value;
  });
  document.querySelectorAll("[data-i18n-aria-label]").forEach((node) => {
    node.setAttribute("aria-label", t(node.dataset.i18nAriaLabel));
  });
  document.querySelectorAll(".language-control select").forEach((node) => { node.value = currentLanguage; });
  if (globalThis.location?.href) document.querySelectorAll('a[href]').forEach((node) => {
    const href = node.getAttribute("href");
    if (node.dataset.publicGuide) node.setAttribute("href", publicDeveloperGuideUrl(node.dataset.publicGuide));
    else if (href && !href.startsWith("#")) node.setAttribute("href", localizedPortalUrl(href, location.href));
  });
}
