export function initI18n() {
  document.querySelectorAll(".language-control select").forEach((select) => {
    select.replaceChildren(...languages.map(([code, label]) => new Option(label, code)));
    select.addEventListener("change", () => {
      currentLanguage = select.value;
      try { localStorage.setItem("kasamila_portal_language", currentLanguage); } catch {}
      if (globalThis.document?.body?.dataset.portalApp === "true") {
        history.replaceState(history.state, "", localizedPortalUrl(location.href, location.href));
      }
      applyTranslations();
      window.dispatchEvent(new Event("kasamila:language-changed"));
    });
  });
  applyTranslations();
}
